56	  configTemplate = pkgs.writeText "opencode.json.tmpl" (builtins.toJSON opencodeConfig);
57	
58	  # opencode-model-stats adds `session_id`/`message_id` headers alongside the
59	  # canonical `x-opencode-*` forms. Modular's edge proxy (Envoy) 400s any
60	  # request with an underscore-named header before it reaches the model server.
61	  # Strip those two lines from the cached plugin source — the x- prefixed
62	  # headers carry the same data.
63	  patchModelStats = pkgs.writeShellScript "opencode-patch-model-stats" ''
64	    set -eu
65	    shopt -s nullglob
66	    for f in "$HOME"/.cache/opencode/packages/opencode-model-stats@*/node_modules/opencode-model-stats/src/server.ts; do
67	      if ${pkgs.gnugrep}/bin/grep -q '\["session_id"\]\|\["message_id"\]' "$f"; then
68	        ${pkgs.gnused}/bin/sed -i \
69	          -e '/output\.headers\["session_id"\] *= *ctx\.sessionID/d' \
70	          -e '/output\.headers\["message_id"\] *= *ctx\.messageID/d' \
71	          "$f"
72	      fi
73	    done
74	  '';
