78	    (final: prev: {
79	      opencode = prev.symlinkJoin {
80	        name = "opencode-${prev.opencode.version or "wrapped"}-mcloudpatch";
81	        paths = [ prev.opencode ];
82	        nativeBuildInputs = [ prev.makeWrapper ];
83	        postBuild = ''
84	          rm -f $out/bin/opencode
85	          makeWrapper ${prev.opencode}/bin/opencode $out/bin/opencode \
86	            --run ${patchModelStats} \
