93	  # opencode.json is rendered at activation by injecting the sops-decrypted
94	  # Modular API key into provider.mcloud.options.apiKey. Not symlinked into the
95	  # nix store so the secret never leaks to world-readable /nix/store paths.
96	  home.activation.opencodeConfig = lib.hm.dag.entryAfter [ "writeBoundary" "sops-nix" ] ''
97	    DEST="$HOME/.config/opencode/opencode.json"
98	    TMPL="${configTemplate}"
99	    MCLOUD_KEY_FILE="$HOME/.config/local-auto-mode/api-key"
100	    MCLOUD_URL_FILE="$HOME/.config/opencode/mcloud-base-url"
101	    KOAG_KEY_FILE="$HOME/.config/opencode/ko-ag-key"
102	    ZAI_KEY_FILE="$HOME/.config/opencode/zai-key"
103	    $DRY_RUN_CMD mkdir -p "$HOME/.config/opencode"
104	    JQ_ARGS=()
105	    JQ_FILTER='.'
106	    if [ -r "$MCLOUD_KEY_FILE" ]; then
107	      JQ_ARGS+=(--rawfile mcloudKey "$MCLOUD_KEY_FILE")
108	      JQ_FILTER="$JQ_FILTER | .provider.mcloud.options.apiKey = (\$mcloudKey | sub(\"\\n$\"; \"\"))"
109	    fi
110	    if [ -r "$MCLOUD_URL_FILE" ]; then
111	      JQ_ARGS+=(--rawfile mcloudUrl "$MCLOUD_URL_FILE")
112	      JQ_FILTER="$JQ_FILTER | .provider.mcloud.options.baseURL = (\$mcloudUrl | sub(\"\\n$\"; \"\"))"
113	    fi
114	    if [ -r "$KOAG_KEY_FILE" ]; then
115	      JQ_ARGS+=(--rawfile koagKey "$KOAG_KEY_FILE")
116	      JQ_FILTER="$JQ_FILTER | .provider.\"ko-ag\".options.apiKey = (\$koagKey | sub(\"\\n$\"; \"\"))"
117	    fi
118	    if [ -e "$ZAI_KEY_FILE" ]; then
119	      JQ_ARGS+=(--rawfile zaiKey "$ZAI_KEY_FILE")
120	      JQ_FILTER="$JQ_FILTER | .provider.\"zai-coding-plan\".options.apiKey = (\$zaiKey | sub(\"\\n$\"; \"\"))"
121	    fi
122	    if [ ''${#JQ_ARGS[@]} -gt 0 ]; then
123	      $DRY_RUN_CMD ${pkgs.jq}/bin/jq "''${JQ_ARGS[@]}" "$JQ_FILTER" "$TMPL" > "$DEST.new"
124	      $DRY_RUN_CMD mv "$DEST.new" "$DEST"
125	      $DRY_RUN_CMD chmod 0600 "$DEST"
126	    else
127	      $DRY_RUN_CMD cp "$TMPL" "$DEST"
128	      $DRY_RUN_CMD chmod 0644 "$DEST"
129	    fi
130	  '';
