133	  # from messages_first (which used "ctrl+g,home"). C-f/C-b mirror
134	  # forward-char/backward-char in confirmation dialogs (select next/prev).
135	  xdg.configFile."opencode/tui.json".text = builtins.toJSON {
136	    "$schema" = "https://opencode.ai/tui.json";
137	    keybinds = {
